, #{ifDesc}
, #{ifProcessTypeCd}
, #{ifConnectionTypeCd}
, #{ruleUseYn}
, #{docLength}
, #{characterset}
, #{eaiid}
, #{firstregUserid}
, TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
, #{firstregUserid}
, TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
, 'N'
)

